text:
Interakcija — Simpsonov paradoks
Interaktivni prikaz gradi transparentan primjer s dvjema skupinama i dvjema podskupinama. Stope unutar podskupina ostaju jednake, dok klizači mijenjaju njihovu zastupljenost u svakoj skupini. Prebacivanje pogleda pokazuje kako različiti utezi mogu proizvesti zbirni rezultat suprotan obrascu unutar obje podskupine.



Prikaži kod
viewof w01_par = Inputs.form({
  pogled: Inputs.select(
    ["Združeno", "Po podskupinama"],
    {value: "Združeno", label: "Pogled"}
  ),
  udio_a: Inputs.range(
    [0, 100],
    {value: 80, step: 5, label: "Udio A u pristupačnijoj podskupini"}
  ),
  udio_b: Inputs.range(
    [0, 100],
    {value: 20, step: 5, label: "Udio B u pristupačnijoj podskupini"}
  )
})









Prikaži kod
w01_tema = Generators.observe(obavijesti =&gt; {
  let revizija = 0;
  const osvjezi = () =&gt; obavijesti(++revizija);
  const promatrac = new MutationObserver(osvjezi);
  const postavke = {
    attributes: true,
    attributeFilter: ["class", "data-bs-theme"]
  };
  promatrac.observe(document.documentElement, postavke);
  promatrac.observe(document.body, postavke);
  osvjezi();
  return () =&gt; promatrac.disconnect();
})









Prikaži kod
{
  w01_tema;
  const css = getComputedStyle(document.documentElement);
  const bojaA = css.getPropertyValue("--tok-data-1").trim();
  const bojaB = css.getPropertyValue("--tok-data-4").trim();
  const tinta = css.getPropertyValue("--tok-ink").trim();
  const linija = css.getPropertyValue("--tok-rule").trim();
  const sans = css.getPropertyValue("--tok-font-sans").trim();
  const postotak = new Intl.NumberFormat("hr-HR", {
    style: "percent",
    maximumFractionDigits: 0
  });

  const stope = [
    {podskupina: "Pristupačnija", skupina: "Skupina A", stopa: 0.80},
    {podskupina: "Pristupačnija", skupina: "Skupina B", stopa: 0.90},
    {podskupina: "Zahtjevnija", skupina: "Skupina A", stopa: 0.20},
    {podskupina: "Zahtjevnija", skupina: "Skupina B", stopa: 0.30}
  ];

  const udioA = w01_par.udio_a / 100;
  const udioB = w01_par.udio_b / 100;
  const ukupno = [
    {
      podskupina: "Združeno",
      skupina: "Skupina A",
      stopa: udioA * 0.80 + (1 - udioA) * 0.20
    },
    {
      podskupina: "Združeno",
      skupina: "Skupina B",
      stopa: udioB * 0.90 + (1 - udioB) * 0.30
    }
  ];

  const razdvojeno = w01_par.pogled === "Po podskupinama";
  const celija = document.querySelector(".widget-frame .cell");
  const stilCelije = celija ? getComputedStyle(celija) : null;
  const lokalnaSirina = celija
    ? celija.clientWidth -
      parseFloat(stilCelije.paddingLeft) -
      parseFloat(stilCelije.paddingRight)
    : width;
  const sirinaGrafa = Math.max(240, Math.min(width, lokalnaSirina));
  const usko = sirinaGrafa &lt; 480;
  const podaci = razdvojeno ? stope : ukupno;
  const raspored = razdvojeno
    ? (usko ? {fy: "podskupina"} : {fx: "podskupina"})
    : {};
  const marks = [
    Plot.barY(podaci, {
      x: "skupina",
      y: "stopa",
      fill: "skupina",
      inset: 18,
      ...raspored
    }),
    Plot.text(podaci, {
      x: "skupina",
      y: "stopa",
      text: d =&gt; postotak.format(d.stopa),
      dy: -9,
      fill: tinta,
      ...raspored
    }),
    Plot.ruleY([0], {stroke: linija})
  ];

  return Plot.plot({
    width: sirinaGrafa,
    height: razdvojeno ? (usko ? 500 : 330) : (usko ? 340 : 300),
    marginLeft: usko ? 52 : 58,
    marginRight: usko ? 14 : 24,
    marginBottom: 48,
    marginTop: razdvojeno ? (usko ? 24 : 34) : (usko ? 28 : 20),
    style: {
      background: "transparent",
      fontFamily: sans,
      fontSize: usko ? "12px" : "13px"
    },
    color: {
      domain: ["Skupina A", "Skupina B"],
      range: [bojaA, bojaB],
      legend: false
    },
    x: {label: null},
    fx: razdvojeno && !usko ? {label: null} : undefined,
    fy: razdvojeno && usko ? {label: null} : undefined,
    y: {
      label: "Stopa uspjeha",
      domain: [0, 1],
      tickFormat: d =&gt; postotak.format(d)
    },
    marks
  });
}









Slika 1: Zbirne stope i stope po podskupinama u konstruiranom primjeru Simpsonova paradoksa.





Što isprobati.

Najprije usporedite samo zbirne stope i zapišite koja skupina izgleda uspješnije.
Uključite prikaz podskupina i provjerite ostaje li smjer razlike jednak.
Promijenite zastupljenost podskupina bez mijenjanja njihovih stopa i promatrajte kada se zbirni zaključak preokrene.
Postavite obje zastupljenosti na istu vrijednost i provjerite je li obrat tada uopće moguć.

Posljednji korak pokazuje granicu pojave. Dok su obje skupine jednako raspoređene po podskupinama, zbirna usporedba slijedi usporedbu unutar podskupina i obrata nema. Obrat traži da se skupine razlikuju i po tome gdje su mjerene, a ne samo po tome kako su prošle. Zbirna razlika zato uvijek sadrži dva sastojka, uspješnost i sastav, koje bez razdvajanja podataka ne možemo razlučiti.

Privid pristranosti u zbirnoj stopi. Tvrdnja da su muškarci u Berkeleyju 1973. primani češće od žena aritmetički je točna za šest najvećih odjela (Bickel i sur. 1975.). Problem nastaje tek kada tu zbirnu razliku pretvorimo u objašnjenje postupka upisa. Ukupna stopa istodobno spaja odluke različitih odjela i različitu raspodjelu prijava među njima.
Odgovorno čitanje zato ne odbacuje zbirnu stopu, ali od nje traži pomoćne informacije. Potrebni su brojevi prijava i primljenih kandidata unutar svakog odjela te objašnjenje zbog čega je odjel relevantna podjela. Tek tada vidimo koji dio razlike nastaje unutar usporedivih skupina, a koji zbog njihova različitog sastava.


Asistent može brzo izračunati zbirne stope i ponoviti izračun po podskupinama, ali mu treba dati stvarne brojnike i nazivnike. Nakon odgovora valja provjeriti daju li zbrojevi ćelija objavljene ukupne vrijednosti i je li svaka stopa izračunata s odgovarajućim nazivnikom. Modeli osobito lako nadopune ćeliju koja nedostaje ili svaku razliku između zbirnog i grupiranog prikaza proglase Simpsonovim paradoksom.

Usporedi zbirne stope prijma sa stopama po odjelima. Prikaži broj prijava, broj primljenih i nazivnik svake stope. Opiši kako sastav prijava mijenja zbirni rezultat, ali nemoj iz tih tablica izvoditi kauzalni zaključak.



Zbirna stopa prijma bila je viša za muškarce, dok je u četiri od šest odjela stopa za žene bila barem jednaka stopi za muškarce (Bickel i sur. 1975.). Žene su se češće prijavljivale na selektivnije odjele (Bickel i sur. 1975.). Stoga je izbor odjela uzrokovao cijeli zbirni jaz.

Interakcija — Prikaz konfundera
Prikaz pokazuje odnos dviju varijabli prije i nakon razlikovanja jedinica prema trećoj varijabli. Opažanja ostaju ista, ali se mijenja usporedba. Pomak ishoda povezan s trećom varijablom može zbirnu vezu preokrenuti iako je odnos unutar obiju podskupina stabilan.



Prikaži kod
viewof w02_par = Inputs.form({
  pogled: Inputs.select(
    ["Zbirno", "Prema trećoj varijabli"],
    {value: "Zbirno", label: "Pogled"}
  ),
  pomak: Inputs.range(
    [0, 5],
    {
      value: 4,
      step: 0.25,
      label: "Razlika ishoda povezana s trećom varijablom"
    }
  )
})









Prikaži kod
w02_tema = Generators.observe(obavijesti =&gt; {
  let revizija = 0;
  const osvjezi = () =&gt; obavijesti(++revizija);
  const promatrac = new MutationObserver(osvjezi);
  const postavke = {
    attributes: true,
    attributeFilter: ["class", "data-bs-theme"]
  };
  promatrac.observe(document.documentElement, postavke);
  promatrac.observe(document.body, postavke);
  osvjezi();
  return () =&gt; promatrac.disconnect();
})









Prikaži kod
{
  w02_tema;
  const css = getComputedStyle(document.documentElement);
  const tinta = css.getPropertyValue("--tok-data-1").trim();
  const tamna = css.getPropertyValue("--tok-data-2").trim();
  const svijetla = css.getPropertyValue("--tok-data-4").trim();
  const prigusena = css.getPropertyValue("--tok-ink-mute").trim();
  const povrsina = css.getPropertyValue("--tok-surface").trim();
  const sans = css.getPropertyValue("--tok-font-sans").trim();
  const razine = ["Niža vrijednost", "Viša vrijednost"];

  const podaci = Array.from({length: 32}, (_, i) =&gt; {
    const visoka = i &gt;= 16;
    const red = i % 16;
    const u = (red - 7.5) / 7.5;
    const izlozenost = (visoka ? 6.6 : 2.8) + 1.6 * u;
    const odstupanje =
      0.28 * Math.sin((red + 1) * 2.3) +
      0.10 * Math.cos((red + 1) * 1.1);
    const ishod =
      7.2 - 0.55 * izlozenost + (visoka ? w02_par.pomak : 0) + odstupanje;
    return {
      izlozenost,
      ishod,
      treca: visoka ? razine[1] : razine[0]
    };
  });

  function pravac(redovi, serija) {
    const mx = d3.mean(redovi, d =&gt; d.izlozenost);
    const my = d3.mean(redovi, d =&gt; d.ishod);
    const brojnik = d3.sum(
      redovi,
      d =&gt; (d.izlozenost - mx) * (d.ishod - my)
    );
    const nazivnik = d3.sum(
      redovi,
      d =&gt; (d.izlozenost - mx) ** 2
    );
    const nagib = brojnik / nazivnik;
    const odsjecak = my - nagib * mx;
    const xmin = d3.min(redovi, d =&gt; d.izlozenost);
    const xmax = d3.max(redovi, d =&gt; d.izlozenost);
    return [
      {x: xmin, y: odsjecak + nagib * xmin, serija},
      {x: xmax, y: odsjecak + nagib * xmax, serija}
    ];
  }

  const razdvojeno = w02_par.pogled === "Prema trećoj varijabli";
  const niza = podaci.filter(d =&gt; d.treca === razine[0]);
  const visa = podaci.filter(d =&gt; d.treca === razine[1]);
  const celija = document.querySelector(".widget-frame .cell");
  const stilCelije = celija ? getComputedStyle(celija) : null;
  const lokalnaSirina = celija
    ? celija.clientWidth -
      parseFloat(stilCelije.paddingLeft) -
      parseFloat(stilCelije.paddingRight)
    : width;
  const sirinaGrafa = Math.max(200, Math.min(width, lokalnaSirina));
  const usko = sirinaGrafa &lt; 480;
  const pomakOznake = usko
    ? {dx: -10, dy: -12, textAnchor: "end"}
    : {dx: 10, dy: -8, textAnchor: "start"};
  let marks;

  if (razdvojeno) {
    const linijaNiza = pravac(niza, razine[0]);
    const linijaVisa = pravac(visa, razine[1]);
    marks = [
      Plot.dot(podaci, {
        x: "izlozenost",
        y: "ishod",
        fill: "treca",
        r: 4.2,
        fillOpacity: 0.78
      }),
      Plot.line(linijaNiza, {
        x: "x",
        y: "y",
        stroke: tamna,
        strokeWidth: 2
      }),
      Plot.line(linijaVisa, {
        x: "x",
        y: "y",
        stroke: svijetla,
        strokeWidth: 2,
        strokeDasharray: "6,4"
      }),
      Plot.text(
        [
          {...linijaNiza[1], oznaka: "niža vrijednost"},
          {...linijaVisa[1], oznaka: "viša vrijednost"}
        ],
        {
          x: "x",
          y: "y",
          text: "oznaka",
          ...pomakOznake,
          fontSize: usko ? 11 : 12,
          fill: prigusena,
          stroke: povrsina,
          strokeWidth: 3,
          paintOrder: "stroke"
        }
      )
    ];
  } else {
    const linija = pravac(podaci, "Zbirno");
    marks = [
      Plot.dot(podaci, {
        x: "izlozenost",
        y: "ishod",
        fill: tinta,
        r: 4.2,
        fillOpacity: 0.72
      }),
      Plot.line(linija, {
        x: "x",
        y: "y",
        stroke: tamna,
        strokeWidth: 2.2
      }),
      Plot.text(
        [{...linija[1], oznaka: "zbirna veza"}],
        {
          x: "x",
          y: "y",
          text: "oznaka",
          ...pomakOznake,
          fontSize: usko ? 11 : 12,
          fill: prigusena,
          stroke: povrsina,
          strokeWidth: 3,
          paintOrder: "stroke"
        }
      )
    ];
  }

  return Plot.plot({
    width: sirinaGrafa,
    height: usko ? 420 : 330,
    marginLeft: usko ? 50 : 55,
    marginRight: usko ? 18 : 112,
    marginBottom: 48,
    style: {
      background: "transparent",
      fontFamily: sans,
      fontSize: usko ? "12px" : "13px"
    },
    color: {
      domain: razine,
      range: [tamna, svijetla],
      legend: false
    },
    x: {label: "Izloženost", grid: true},
    y: {label: "Ishod", grid: true},
    marks
  });
}









Slika 1: Ista opažanja prikazana zbirno i prema trećoj varijabli u konstruiranom primjeru.





Što isprobati.

Promatrajte početnu vezu bez treće varijable.
Uključite konfundirajuću varijablu i usporedite smjer veze.
Promijenite njezinu povezanost s ishodom i pronađite slučaj u kojem se početni zaključak preokreće.
Postavite tu povezanost na nulu i provjerite razlikuju li se tada dva prikaza uopće.

Posljednji korak imenuje uvjet. Dok treća varijabla ne pomiče ishod, oba prikaza govore isto i njezino uključivanje ništa ne mijenja. Konfundiranje traži da varijabla bude povezana s objema promatranim veličinama istodobno, a ne samo da postoji u podacima. Odatle slijedi i praktična posljedica. Popis mogućih konfundera nije popis svega što je izmjereno, nego kratak popis onoga za što imamo razlog vjerovati da djeluje na obje strane, i taj razlog dolazi iz teorije, a ne iz tablice.

Što mjeri stopa prijma. Zbirna stopa u Berkeleyju opisivala je ishod prijava, ali nije sama mjerila namjeru, kriterije odlučivanja ni iskustvo kandidata (Bickel i sur. 1975.). Pretvaranje te stope u potpunu ocjenu pravednosti preskače operacionalizaciju pojma pravednosti. Pravednost se može operacionalizirati kao jednak ishod među skupinama, kao jednak postupak prema jednako kvalificiranim kandidatima ili kao jednaka dostupnost samog odjela, i te tri mjere u ovim podacima ne daju isti odgovor.
Odgovorno čitanje zato najprije pita koja je jedinica analize i koje su varijable dostupne. Jedinica su ovdje prijave, a ne osobe, pa kandidat koji se prijavio na dva odjela ulazi dvaput. Dostupne su varijable ishod, spol i odjel, dok kvaliteta prijave i savjet primljen prije prijave nisu izmjereni. Tek nakon toga ima smisla procjenjivati koji dizajn može razlikovati suparnička objašnjenja, a ovaj skup podataka nastao je bez ikakva dizajna, jer su ga proizveli sami upisni postupci.


Asistent može pretvoriti istraživačko pitanje u nacrt varijabli i upozoriti na moguće konfundere. Njegov popis nije dokaz da su mjere valjane. Treba provjeriti odgovara li svaka predložena varijabla stvarnom instrumentu, tko nedostaje iz okvira uzorkovanja i dopušta li dizajn kauzalni zaključak.
Dva su promašaja ovdje osobito česta. Modeli redovito predlažu popis konfundera koji je dug i uvjerljiv, a pritom ne razlikuju varijable koje prethode pretpostavljenom uzroku od onih koje su njegova posljedica, iako se prilagodba za posljedicu ne smije provesti. Uz to skloni su kauzalnom jeziku i za nacrte koji ga ne podnose, pa opažačku studiju opisuju glagolima poput utječe ili smanjuje. Provjerite svaku predloženu varijablu prema tome kada nastaje i preformulirajte svaku rečenicu koja tvrdi djelovanje.

Za ovo istraživačko pitanje predloži jedinicu analize, način mjerenja ishoda, mogući konfundirajući čimbenik i dizajn. Za svaku predloženu varijablu navedi nastaje li prije ili poslije pretpostavljenog uzroka. Za svaku odluku navedi što se iz prikupljenih podataka neće moći zaključiti.



U opažačkoj anketi studenti koji dulje koriste društvene mreže prijavili su niže povjerenje u institucije. Obje su varijable izmjerene istim upitnikom i analiza je uključila dob. Rezultat zato dokazuje da dulje korištenje društvenih mreža smanjuje povjerenje.

Interakcija — Istraživač margine pogreške
Istraživač prikazuje približnu marginu pogreške uzorka pri različitim veličinama i procijenjenim udjelima. Zaseban klizač uvodi poznatu sustavnu pristranost. Interval se tada može sužavati oko precizno procijenjene pogrešne vrijednosti.



Prikaži kod
viewof w03_par = Inputs.form({
  n: Inputs.range(
    [100, 3000],
    {value: 1000, step: 100, label: "Veličina uzorka"}
  ),
  udio: Inputs.range(
    [10, 90],
    {value: 52, step: 1, label: "Procijenjeni udio u postocima"}
  ),
  pristranost: Inputs.range(
    [-10, 10],
    {
      value: 0,
      step: 1,
      label: "Pristranost procjene u postotnim bodovima"
    }
  )
})









Prikaži kod
w03_tema = Generators.observe(obavijesti =&gt; {
  let revizija = 0;
  const osvjezi = () =&gt; obavijesti(++revizija);
  const promatrac = new MutationObserver(osvjezi);
  const postavke = {
    attributes: true,
    attributeFilter: ["class", "data-bs-theme"]
  };
  promatrac.observe(document.documentElement, postavke);
  promatrac.observe(document.body, postavke);
  osvjezi();
  return () =&gt; promatrac.disconnect();
})









Prikaži kod
{
  w03_tema;
  const css = getComputedStyle(document.documentElement);
  const tinta = css.getPropertyValue("--tok-data-1").trim();
  const istinaBoja = css.getPropertyValue("--tok-data-2").trim();
  const intervalBoja = css.getPropertyValue("--tok-data-4").trim();
  const prigusena = css.getPropertyValue("--tok-ink-mute").trim();
  const sans = css.getPropertyValue("--tok-font-sans").trim();
  const postotak = new Intl.NumberFormat("hr-HR", {
    style: "percent",
    minimumFractionDigits: 0,
    maximumFractionDigits: 1
  });
  const decimalni = new Intl.NumberFormat("hr-HR", {
    minimumFractionDigits: 1,
    maximumFractionDigits: 1
  });

  const procjena = w03_par.udio / 100;
  const pristranost = w03_par.pristranost / 100;
  const istina = procjena - pristranost;
  const margina = 1.96 * Math.sqrt(
    procjena * (1 - procjena) / w03_par.n
  );
  const donja = Math.max(0, procjena - margina);
  const gornja = Math.min(1, procjena + margina);
  const poklapanje = Math.abs(pristranost) &lt; 1e-9;

  const marks = [
    Plot.ruleY(
      [{y: 0, donja, gornja}],
      {
        y: "y",
        x1: "donja",
        x2: "gornja",
        stroke: intervalBoja,
        strokeWidth: 8,
        strokeLinecap: "round"
      }
    ),
    Plot.dot(
      [
        {x: donja, y: 0},
        {x: gornja, y: 0}
      ],
      {x: "x", y: "y", r: 3.6, fill: intervalBoja}
    ),
    Plot.dot(
      [{x: procjena, y: 0}],
      {x: "x", y: "y", r: 7, fill: tinta}
    ),
    Plot.text(
      [{
        x: (donja + gornja) / 2,
        y: 0.26,
        oznaka: `približna margina ± ${decimalni.format(100 * margina)} boda`
      }],
      {x: "x", y: "y", text: "oznaka", fill: prigusena}
    )
  ];

  if (poklapanje) {
    marks.push(
      Plot.text(
        [{
          x: procjena,
          y: -0.25,
          oznaka: `procjena i pretpostavljena istina ${postotak.format(procjena)}`
        }],
        {x: "x", y: "y", text: "oznaka", fill: prigusena}
      )
    );
  } else {
    marks.push(
      Plot.dot(
        [{x: istina, y: 0}],
        {
          x: "x",
          y: "y",
          r: 6.5,
          symbol: "diamond",
          fill: istinaBoja
        }
      ),
      Plot.text(
        [
          {
            x: procjena,
            y: -0.25,
            oznaka: `procjena ${postotak.format(procjena)}`
          },
          {
            x: istina,
            y: 0.42,
            oznaka: `pretpostavljena istina ${postotak.format(istina)}`
          }
        ],
        {x: "x", y: "y", text: "oznaka", fill: prigusena}
      )
    );
  }

  const celija = document.querySelector(".widget-frame .cell");
  const stilCelije = celija ? getComputedStyle(celija) : null;
  const lokalnaSirina = celija
    ? celija.clientWidth -
      parseFloat(stilCelije.paddingLeft) -
      parseFloat(stilCelije.paddingRight)
    : width;
