    {value: 50, label: "Broj intervala"}
  )
})









Prikaži kod
w09_intervali = {
  const rng = d3.randomLcg(908);
  const normalna = d3.randomNormal.source(rng)(0, 1);
  const kriticna = {
    "90 %": 1.645,
    "95 %": 1.960,
    "99 %": 2.576
  }[w09_par.razina];
  const pogreska = 1 / Math.sqrt(w09_par.n);

  return Array.from({length: w09_par.k}, (_, i) =&gt; {
    let zbroj = 0;
    for (let j = 0; j &lt; w09_par.n; j += 1) zbroj += normalna();
    const procjena = zbroj / w09_par.n;
    const donja = procjena - kriticna * pogreska;
    const gornja = procjena + kriticna * pogreska;
    return {
      red: i + 1,
      procjena,
      donja,
      gornja,
      obuhvaca: donja &lt;= 0 && gornja &gt;= 0
    };
  });
}









