        x: "n",
        y: "snaga",
        stroke: krivulja,
        strokeWidth: 2
      }),
      Plot.dot([odabrana], {
        x: "n",
        y: "snaga",
        fill: naglasak,
        stroke: tinta,
        r: 5
      }),
      Plot.ruleY([0], {stroke: linija})
    ]
  });

  return html`&lt;div&gt;
