        x1: "ocekivano",
        x2: "opazeno",
        stroke: linija,
        strokeWidth: 2
      }),
      Plot.dot(celije, {
        x: "ocekivano",
        y: "celija",
        symbol: "diamond",
        fill: povrsina,
        stroke: ocekivano,
        strokeWidth: 2,
        r: 6
      }),
      Plot.dot(celije, {
        x: "opazeno",
        y: "celija",
        fill: tinta,
        r: 5.5
      }),
      Plot.text(celije, {
        x: d =&gt; Math.max(d.opazeno, d.ocekivano),
        y: "celija",
        text: d =&gt; broj.format(d.doprinos),
        dx: sirina &lt; 480 ? 10 : 14,
