    {value: 5, step: 1, label: "Stvarna razlika"}
  ),
  sd: Inputs.range(
    [4, 20],
    {value: 10, step: 1, label: "Standardna devijacija ishoda"}
  )
})









Prikaži kod
{
  const tinta = "var(--tok-ink)";
  const skupinaA = "var(--tok-data-2)";
  const skupinaB = "var(--tok-data-4)";
  const procjene = "var(--tok-data-5)";
  const naglasak = "var(--tok-accent-deep)";
  const povrsina = "var(--tok-surface)";
  const linija = "var(--tok-rule)";
  const sans = "var(--tok-font-sans)";
  const broj = new Intl.NumberFormat("hr-HR", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2
  });
  const postotak = new Intl.NumberFormat("hr-HR", {
    style: "percent",
    maximumFractionDigits: 0
  });
  const rng = d3.randomLcg(1414);
  const standardna = d3.randomNormal.source(rng)(0, 1);
  const korelacija = 0.65;

  let skupina1;
  let skupina2;
  let standardnaPogreska;

  if (w14_par.dizajn === "Uparena mjerenja") {
    const parovi = Array.from({length: w14_par.n}, () =&gt; {
      const z1 = standardna();
      const z2 = standardna();
      return {
        a: w14_par.sd * z1,
        b: w14_par.razlika + w14_par.sd *
          (korelacija * z1 + Math.sqrt(1 - korelacija ** 2) * z2)
      };
    });
    skupina1 = parovi.map(d =&gt; d.a);
    skupina2 = parovi.map(d =&gt; d.b);
    standardnaPogreska =
      w14_par.sd * Math.sqrt(2 * (1 - korelacija) / w14_par.n);
  } else {
    skupina1 = Array.from(
      {length: w14_par.n},
      () =&gt; w14_par.sd * standardna()
    );
    skupina2 = Array.from(
      {length: w14_par.n},
      () =&gt; w14_par.razlika + w14_par.sd * standardna()
    );
    standardnaPogreska = w14_par.sd * Math.sqrt(2 / w14_par.n);
  }

  const procijenjeneRazlike = Array.from(
    {length: 1500},
    () =&gt; w14_par.razlika + standardnaPogreska * standardna()
  );
  const serije = [
    {panel: "Skupina A u jednom uzorku", vrijednosti: skupina1},
    {panel: "Skupina B u jednom uzorku", vrijednosti: skupina2},
    {panel: "Razlike kroz ponavljanja", vrijednosti: procijenjeneRazlike}
  ];
  const sveVrijednosti = serije.flatMap(d =&gt; d.vrijednosti);
  const donja = d3.min(sveVrijednosti);
  const gornja = d3.max(sveVrijednosti);
  const raspon = Math.max(1, gornja - donja);
  const domena = [donja - 0.04 * raspon, gornja + 0.04 * raspon];
  const binoviUzorak = d3.bin().domain(domena).thresholds(28);
  const binoviProcjene = d3.bin().domain(domena).thresholds(120);
  const histogrami = serije.flatMap(serija =&gt; {
    const binovi = serija.panel === "Razlike kroz ponavljanja"
      ? binoviProcjene
      : binoviUzorak;
    return binovi(serija.vrijednosti).map(bin =&gt; ({
      panel: serija.panel,
      x1: bin.x0,
      x2: bin.x1,
      udio: bin.length / serija.vrijednosti.length
    }));
  });
  const najvisiUdio = d3.max(histogrami, d =&gt; d.udio);
  const gornjaGranicaY = Math.max(0.01, najvisiUdio * 1.3);
  const sredine = [
    {panel: "Skupina A u jednom uzorku", vrijednost: 0},
    {panel: "Skupina B u jednom uzorku", vrijednost: w14_par.razlika}
  ];
  const opisDizajna = w14_par.dizajn === "Uparena mjerenja"
    ? "u uparenom dizajnu uz korelaciju 0,65"
    : "u dizajnu neovisnih skupina";
  const statusTekst =
    `Standardna pogreška iznosi ${broj.format(standardnaPogreska)} ` +
    `${opisDizajna}.`;
  const celija = document.querySelector(".widget-frame .cell");
  const stilCelije = celija ? getComputedStyle(celija) : null;
  const lokalnaSirina = celija
    ? celija.clientWidth -
      parseFloat(stilCelije.paddingLeft) -
      parseFloat(stilCelije.paddingRight)
    : width;
  const sirina = Math.max(200, Math.min(width, lokalnaSirina));
  const vrloUsko = sirina &lt; 240;

  const graf = Plot.plot({
    width: sirina,
    height: sirina &lt; 480 ? 560 : 500,
    marginLeft: 62,
    marginBottom: 52,
    style: {
      background: "transparent",
      color: tinta,
      fontFamily: sans,
      fontSize: "13px"
    },
    color: {
      domain: [
        "Skupina A u jednom uzorku",
        "Skupina B u jednom uzorku",
        "Razlike kroz ponavljanja"
      ],
      range: [skupinaA, skupinaB, procjene],
      legend: false
    },
    x: {
      label: vrloUsko
        ? "Ishod ili procijenjena razlika"
        : "Vrijednost ishoda ili procijenjene razlike",
      domain: domena,
      tickFormat: d =&gt; broj.format(d)
    },
    y: {
      label: "Udio opažanja",
      domain: [0, gornjaGranicaY],
      grid: true,
      ticks: sirina &lt; 480 ? 4 : 5,
      tickFormat: d =&gt; postotak.format(d)
    },
    fy: {label: null, axis: null},
    marks: [
      Plot.rectY(histogrami, {
        x1: "x1",
        x2: "x2",
        y: "udio",
        fy: "panel",
        fill: "panel",
        inset: 0.5
      }),
      Plot.ruleX(sredine, {
        x: "vrijednost",
        fy: "panel",
        stroke: tinta,
        strokeDasharray: "3,3"
      }),
      Plot.ruleX(
        [{panel: "Razlike kroz ponavljanja", vrijednost: w14_par.razlika}],
        {
          x: "vrijednost",
          fy: "panel",
          stroke: naglasak,
          strokeWidth: 1.5
        }
      ),
      Plot.text(
        [
          {
            panel: "Skupina A u jednom uzorku",
            x: domena[1] - 0.025 * raspon,
            y: gornjaGranicaY * 0.93,
            oznaka: "Skupina A · uzorak"
          },
          {
            panel: "Skupina B u jednom uzorku",
            x: domena[1] - 0.025 * raspon,
            y: gornjaGranicaY * 0.93,
            oznaka: "Skupina B · uzorak"
          },
          {
            panel: "Razlike kroz ponavljanja",
            x: domena[1] - 0.025 * raspon,
            y: gornjaGranicaY * 0.93,
            oznaka: "Razlike · ponavljanja"
          }
        ],
        {
          x: "x",
          y: "y",
          fy: "panel",
          text: "oznaka",
          textAnchor: "end",
          dx: -2,
          dy: 4,
          fill: tinta,
          stroke: povrsina,
          strokeWidth: 3,
          paintOrder: "stroke",
          fontSize: sirina &lt; 480 ? "11px" : "12px",
          fontWeight: 600
        }
      ),
      Plot.ruleY([0], {stroke: linija})
    ]
  });

  const okvir = document.createElement("div");
  const status = document.createElement("p");
  status.className = "small";
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  status.textContent = statusTekst;
  okvir.append(status, graf);
  return okvir;
}









Slika 1: Jedan simulirani uzorak dviju skupina i raspodjela procijenjene razlike kroz ponovljene uzorke.





Što isprobati.

Povećajte stvarnu razliku uz jednaku raspršenost.
Povećajte raspršenost uz jednaku razliku i pogledajte oba panela.
Povećajte broj jedinica bez promjene razlike i raspršenosti.
Prebacite dizajn u upareni uz sve ostalo nepromijenjeno.

Posljednji korak pomiče samo jednu postavku, a raspodjela procjena vidljivo se sužava. Uparivanje ne mijenja ni stvarnu razliku ni raspršenost ishoda, nego uklanja onaj dio razlike među mjerenjima koji potječe od razlika među samim jedinicama. Ta dobit postoji samo dok analiza vezu unutar para zadrži.

Interakcija — Dekompozicija varijance
Sljedeći prikaz razdvaja dva izvora rasipanja koje ukupni graf spaja. Okomite trake pokazuju koliko je svaka skupna sredina udaljena od zajedničke, a točke koliko su pojedinci raspršeni oko svoje skupne sredine. Čitatelj pomiče sredine i raspršenost odvojeno, pa se vidi da razmak među skupinama sam po sebi ne određuje ništa.



Prikaži kod
viewof w15_par = Inputs.form({
  sredina_a: Inputs.range([35, 65], {
    value: 46, step: 1, label: "Sredina skupine A:"
  }),
  sredina_b: Inputs.range([35, 65], {
    value: 52, step: 1, label: "Sredina skupine B:"
  }),
  sredina_c: Inputs.range([35, 65], {
    value: 58, step: 1, label: "Sredina skupine C:"
  }),
  rasprsenost: Inputs.range([2, 14], {
    value: 6, step: 1, label: "Standardna devijacija unutar skupina:"
  })
})









Prikaži kod
{
  const tinta = "var(--widget-ink)";
  const priguseno = "var(--tok-ink-mute)";
  const pravilo = "var(--widget-grid)";
  const povrsina = "var(--tok-surface)";
  const podatak = "var(--widget-fill)";
  const naglasak = "var(--widget-emphasis)";
  const formatBroj = new Intl.NumberFormat("hr-HR", {
    minimumFractionDigits: 1,
    maximumFractionDigits: 1
  });

  const n = 24;
  const sredine = [
    {skupina: "A", x: 1, sredina: w15_par.sredina_a},
    {skupina: "B", x: 2, sredina: w15_par.sredina_b},
    {skupina: "C", x: 3, sredina: w15_par.sredina_c}
  ];
  const rng = d3.randomLcg(1515);
  const normalna = d3.randomNormal.source(rng)(0, 1);

  const opazanja = sredine.flatMap(s =&gt; {
    const sirovo = Array.from({length: n}, normalna);
    const m = d3.mean(sirovo);
    const sd = d3.deviation(sirovo);
    return sirovo.map(v =&gt; ({
      skupina: s.skupina,
      x: s.x,
      xPomak: s.x + (rng() - 0.5) * 0.34,
      ishod: s.sredina + w15_par.rasprsenost * (v - m) / sd
    }));
  });

  const zajednicka = d3.mean(opazanja, d =&gt; d.ishod);
  const sazeci = sredine.map(s =&gt; ({
    ...s,
    zajednicka
  }));
  const ssIzmedu = n * d3.sum(sredine, s =&gt;
    (s.sredina - zajednicka) ** 2);
  const ssUnutar = d3.sum(opazanja, d =&gt; {
    const m = sredine[d.x - 1].sredina;
    return (d.ishod - m) ** 2;
  });
  const msIzmedu = ssIzmedu / (sredine.length - 1);
  const msUnutar = ssUnutar / (sredine.length * (n - 1));
  const fOmjer = msIzmedu / msUnutar;
  const raspon = d3.extent(opazanja, d =&gt; d.ishod);
  const odmak = Math.max(3, (raspon[1] - raspon[0]) * 0.08);
  const celija =
    document.getElementById("fig-w15")?.closest(".cell") ??
    document.querySelector(".widget-frame .cell");
  const stilCelije = celija ? getComputedStyle(celija) : null;
  const lokalnaSirina = celija
    ? celija.clientWidth -
      (parseFloat(stilCelije.paddingLeft) || 0) -
      (parseFloat(stilCelije.paddingRight) || 0)
    : width;
  const sirinaGrafa = Math.max(
    1,
    Math.floor(Math.min(width, lokalnaSirina))
  );
  const mobilno = sirinaGrafa &lt; 480;
  const sazetakTekst =
    `F ${formatBroj.format(fOmjer)} · između ${formatBroj.format(msIzmedu)} · unutar ${formatBroj.format(msUnutar)}`;

  const graf = Plot.plot({
    width: sirinaGrafa,
    height: mobilno ? 400 : 360,
    marginTop: mobilno ? 28 : 20,
    marginRight: 18,
    marginBottom: mobilno ? 50 : 44,
    marginLeft: mobilno ? 58 : 56,
    style: {
      background: "transparent",
      color: tinta,
      fontFamily: "var(--tok-font-mono)",
      fontSize: mobilno ? "15px" : "13px"
    },
    x: {
      label: null,
      domain: [0.55, 3.45],
      ticks: [1, 2, 3],
      tickFormat: d =&gt; mobilno
        ? ["A", "B", "C"][d - 1]
        : `Skupina ${["A", "B", "C"][d - 1]}`
    },
    y: {
      label: "Simulirani ishod",
      domain: [raspon[0] - odmak, raspon[1] + odmak],
      grid: true
    },
    marks: [
      Plot.ruleY([zajednicka], {
        stroke: priguseno,
        strokeDasharray: "5,4"
      }),
      Plot.ruleX(sazeci, {
        x: "x",
        y1: "zajednicka",
        y2: "sredina",
        stroke: naglasak,
        strokeWidth: 5,
        strokeOpacity: 0.5
      }),
      Plot.dot(opazanja, {
        x: "xPomak",
        y: "ishod",
        r: 3.2,
        fill: podatak,
        stroke: povrsina,
        strokeWidth: 0.7
      }),
      Plot.dot(sazeci, {
        x: "x",
        y: "sredina",
        r: 6,
        fill: tinta,
        stroke: povrsina,
        strokeWidth: 1.2
      }),
      Plot.text(sazeci, {
        x: "x",
        y: "sredina",
        text: d =&gt; formatBroj.format(d.sredina),
        dy: -13,
        fill: tinta,
        fontWeight: 600
      }),
      Plot.ruleY([raspon[0] - odmak], {stroke: pravilo})
    ]
  });
  return html`&lt;div&gt;
    ${graf}
    &lt;p class="widget-foot" role="status" aria-live="polite"&gt;${sazetakTekst}.&lt;/p&gt;
  &lt;/div&gt;`;
}









Slika 1: Dekompozicija varijance — skupne sredine, zajednička sredina i raspršenost pojedinačnih opažanja.





Što isprobati.

Postavite sve tri sredine na 52 i zadržite standardnu devijaciju 6.
Razmaknite sredine na 46, 52 i 58 te usporedite novi omjer s prvim.
Zadržite razdvojene sredine i povećajte standardnu devijaciju na 12.

Treći korak ne mijenja nijednu skupnu sredinu, a omjer svejedno pada. Razmak među skupinama nije, dakle, veličina koja odlučuje. Odlučuje njegov odnos prema raspršenosti unutar skupina, jer upravo ona kaže koliko bi razmaka slučaj mogao proizvesti sam od sebe.

Interakcija — Regresijski pravac
Pomični pravac pretvara metodu najmanjih kvadrata u vidljiv kriterij. Svaka promjena nagiba ili odsječka mijenja duljine reziduala i njihov zbroj kvadrata, a uključivanje prethodnog interesa otkriva razliku između zbirnog i prilagođenog odnosa.



Prikaži kod
viewof w16_par = Inputs.form({
  odsječak: Inputs.range([-10, 35], {
    value: 10, step: 1, label: "Odsječak pravca:"
  }),
  nagib: Inputs.range([0, 7], {
    value: 4.5, step: 0.1, label: "Nagib pravca:"
  }),
  drugi: Inputs.toggle({
    value: false, label: "Prikaži model s prethodnim interesom"
  })
})









Prikaži kod
{
  const tinta = "var(--widget-ink)";
  const priguseno = "var(--tok-ink-mute)";
  const pravilo = "var(--widget-grid)";
  const povrsina = "var(--tok-surface)";
  const podatak = "var(--widget-fill)";
  const prilagodeno = "var(--widget-ink-secondary)";
  const naglasak = "var(--widget-emphasis)";
  const formatBroj = new Intl.NumberFormat("hr-HR", {
    maximumFractionDigits: 1
  });
  const rng = d3.randomLcg(1616);
  const normalna = d3.randomNormal.source(rng)(0, 1);

  const podaci = Array.from({length: 52}, () =&gt; {
    const interes = normalna();
    const vrijeme = Math.max(0, 5 + 1.8 * interes + 1.5 * normalna());
    const angazman = 20 + 2.3 * vrijeme + 7 * interes + 4.5 * normalna();
    return {interes, vrijeme, angazman};
  });

  const regresija = (x, y) =&gt; {
    const mx = d3.mean(x);
    const my = d3.mean(y);
    const brojnik = d3.sum(x, (v, i) =&gt; (v - mx) * (y[i] - my));
    const nazivnik = d3.sum(x, v =&gt; (v - mx) ** 2);
    const b = brojnik / nazivnik;
    return {a: my - b * mx, b};
  };
  const x = podaci.map(d =&gt; d.vrijeme);
  const y = podaci.map(d =&gt; d.angazman);
  const z = podaci.map(d =&gt; d.interes);
  const zbirni = regresija(x, y);
  const xPremaZ = regresija(z, x);
  const yPremaZ = regresija(z, y);
  const xOstatak = x.map((v, i) =&gt; v - xPremaZ.a - xPremaZ.b * z[i]);
  const yOstatak = y.map((v, i) =&gt; v - yPremaZ.a - yPremaZ.b * z[i]);
  const prilagodeniNagib =
    d3.sum(xOstatak, (v, i) =&gt; v * yOstatak[i]) /
    d3.sum(xOstatak, v =&gt; v ** 2);
  const prilagodeni = {
    a: d3.mean(y) - prilagodeniNagib * d3.mean(x),
    b: prilagodeniNagib
  };

  const reziduali = podaci.map(d =&gt; ({
    ...d,
    procjena: w16_par.odsječak + w16_par.nagib * d.vrijeme
  }));
  const sse = d3.sum(reziduali, d =&gt;
    (d.angazman - d.procjena) ** 2);
  const sseNajmanji = d3.sum(podaci, d =&gt;
    (d.angazman - zbirni.a - zbirni.b * d.vrijeme) ** 2);
  const xRaspon = d3.extent(x);
  const xOdmak = (xRaspon[1] - xRaspon[0]) * 0.05;
  const xMin = Math.max(0, xRaspon[0] - xOdmak);
  const xMax = xRaspon[1] + xOdmak;
  const linija = model =&gt; [
    {x: xMin, y: model.a + model.b * xMin},
    {x: xMax, y: model.a + model.b * xMax}
  ];
  const korisnikov = {a: w16_par.odsječak, b: w16_par.nagib};
  const sveY = [
    ...y,
    ...linija(korisnikov).map(d =&gt; d.y),
    ...linija(zbirni).map(d =&gt; d.y),
    ...(w16_par.drugi ? linija(prilagodeni).map(d =&gt; d.y) : [])
  ];
  const yRaspon = d3.extent(sveY);
  const yOdmak = Math.max(3, (yRaspon[1] - yRaspon[0]) * 0.07);
  const celija =
    document.getElementById("fig-w16")?.closest(".cell") ??
    document.querySelector(".widget-frame .cell");
  const stilCelije = celija ? getComputedStyle(celija) : null;
  const lokalnaSirina = celija
    ? celija.clientWidth -
      (parseFloat(stilCelije.paddingLeft) || 0) -
      (parseFloat(stilCelije.paddingRight) || 0)
    : width;
  const sirinaGrafa = Math.max(
    1,
    Math.floor(Math.min(width, lokalnaSirina))
  );
  const mobilno = sirinaGrafa &lt; 480;
  const sazetakTekst =
    `Zbroj kvadrata ${formatBroj.format(sse)} · minimum ${formatBroj.format(sseNajmanji)}`;
  const graf = Plot.plot({
    width: sirinaGrafa,
    height: mobilno ? 410 : 365,
    marginTop: 20,
    marginRight: 20,
    marginBottom: mobilno ? 56 : 48,
    marginLeft: mobilno ? 62 : 58,
    style: {
      background: "transparent",
      color: tinta,
      fontFamily: "var(--tok-font-mono)",
      fontSize: mobilno ? "15px" : "13px"
    },
    x: {
      label: "Simulirano vrijeme",
      domain: [xMin, xMax],
      grid: true
    },
    y: {
      label: "Simulirani angažman",
      domain: [yRaspon[0] - yOdmak, yRaspon[1] + yOdmak],
      grid: true
    },
    marks: [
      Plot.ruleX(reziduali, {
        x: "vrijeme",
        y1: "angazman",
        y2: "procjena",
        stroke: naglasak,
        strokeOpacity: 0.35
      }),
      Plot.dot(podaci, {
        x: "vrijeme",
        y: "angazman",
        r: 4,
        fill: podatak,
        stroke: povrsina,
        strokeWidth: 0.8
      }),
      Plot.line(linija(korisnikov), {
        x: "x",
        y: "y",
        stroke: naglasak,
        strokeWidth: 2.8
      }),
      Plot.line(linija(zbirni), {
        x: "x",
        y: "y",
        stroke: tinta,
        strokeWidth: 1.8,
        strokeDasharray: "6,4"
      }),
      ...(w16_par.drugi ? [
        Plot.line(linija(prilagodeni), {
          x: "x",
          y: "y",
          stroke: prilagodeno,
          strokeWidth: 2,
          strokeDasharray: "2,3"
        })
      ] : []),
      Plot.text([{
        x: xMax,
        y: korisnikov.a + korisnikov.b * xMax,
        tekst: mobilno ? "pomični" : "pomični pravac"
      }], {
        x: "x",
        y: "y",
        text: "tekst",
        fill: naglasak,
        dy: -10,
        dx: -5,
        textAnchor: "end",
        fontWeight: 600
      }),
      Plot.text([{
        x: xMax,
        y: zbirni.a + zbirni.b * xMax,
        tekst: mobilno ? "najmanji" : "najmanji kvadrati"
      }], {
        x: "x",
        y: "y",
        text: "tekst",
        fill: tinta,
        dy: 11,
        dx: -5,
        textAnchor: "end",
        fontWeight: 600
      }),
      ...(w16_par.drugi ? [
        Plot.text([{
          x: xMax,
          y: prilagodeni.a + prilagodeni.b * xMax,
          tekst: mobilno ? "uz interes" : "uz jednak interes"
        }], {
          x: "x",
          y: "y",
          text: "tekst",
          fill: prilagodeno,
          dy: 22,
          dx: -5,
          textAnchor: "end",
          fontWeight: 600
        })
      ] : []),
      Plot.ruleY([yRaspon[0] - yOdmak], {stroke: pravilo})
    ]
  });
  return html`&lt;div&gt;
    ${graf}
    &lt;p class="widget-foot" role="status" aria-live="polite"&gt;${sazetakTekst}&lt;/p&gt;
  &lt;/div&gt;`;
}









Slika 1: Regresijski pravac — pomični pravac, reziduali i usporedba zbirnog s prilagođenim nagibom.





Što isprobati.

Mijenjajte odsječak i nagib dok se zbroj kvadrata ne približi prikazanom minimumu.
Povećajte samo nagib za jednu jedinicu i pratite koji se reziduali najviše produljuju.
Uključite model s prethodnim interesom i usporedite njegov nagib sa zbirnim pravcem.


Dvije kulture modeliranja. Breiman je opisao napetost između modela usmjerenih na podatkovni mehanizam i algoritamskih postupaka usmjerenih na predikciju (Breiman 2001.).
Članak koji model naziva „boljim” mora zato navesti kriterij. Bolje pristajanje, stabilniji koeficijent, manja pogreška na novim podacima i uvjerljiviji uzročni dizajn nisu ista postignuća.


Asistent može prilagoditi model, izraditi dijagnostičke grafove i prevesti koeficijente u prozu. Treba mu zadati ulogu svake varijable, referentne kategorije i cilj analize. Provjeravamo kod, jedinice, reziduale, podatke za provjeru predikcije i svaki prijelaz iz povezanosti prema uzroku.

Prilagodi linearni model i protumači koeficijente u izvornim jedinicama. Prikaži intervale, dijagnostiku reziduala i odvojenu provjeru predikcije. Uzročni jezik koristi samo ako ga dizajn izričito opravdava.



Model uključuje dob, obrazovanje i početni rezultat, a rezidualni prikazi ne pokazuju velik problem. Koeficijent korištenja platforme zato predstavlja čisti uzročni učinak korištenja na ishod.

Interakcija — Istraživač pravednosti
Istraživač pravednosti mijenja klasifikacijski prag za dvije skupine s različitim temeljnim stopama, ali jednakom kvalitetom rezultata uvjetno na stvarni ishod. Tako se vidi kako zajednički prag može izjednačiti neke stope pogreške, a ipak proizvesti različitu prediktivnu vrijednost i točnost.



Prikaži kod
viewof w17_par = Inputs.form({
  prag: Inputs.range([0.2, 0.8], {
    value: 0.6, step: 0.05, label: "Zajednički klasifikacijski prag:"
  }),
  temeljna_a: Inputs.range([0.1, 0.6], {
    value: 0.2, step: 0.05, label: "Temeljna stopa skupine A:"
  }),
  temeljna_b: Inputs.range([0.1, 0.6], {
    value: 0.45, step: 0.05, label: "Temeljna stopa skupine B:"
  })
})







Rezultat se učitava.


Prikaži kod
{
  const tinta = "var(--widget-ink)";
  const pravilo = "var(--widget-grid)";
  const bojaA = "var(--widget-ink)";
  const bojaB = "var(--widget-ink-secondary)";
  const formatPostotak = new Intl.NumberFormat("hr-HR", {
    style: "percent",
    maximumFractionDigits: 0
  });
  const rng = d3.randomLcg(1717);
  const normalna = d3.randomNormal.source(rng)(0, 1);
  const ograniči = x =&gt; Math.max(0, Math.min(1, x));
  const negativni = Array.from(
    {length: 6000},
    () =&gt; ograniči(0.30 + 0.18 * normalna())
  );
  const pozitivni = Array.from(
    {length: 6000},
    () =&gt; ograniči(0.70 + 0.18 * normalna())
  );
  const fpr = d3.mean(negativni, d =&gt; d &gt;= w17_par.prag);
  const fnr = d3.mean(pozitivni, d =&gt; d &lt; w17_par.prag);
  const tpr = 1 - fnr;
  const tnr = 1 - fpr;
  const celija =
    document.getElementById("fig-w17")?.closest(".cell") ??
    document.querySelector(".widget-frame .cell");
  const stilCelije = celija ? getComputedStyle(celija) : null;
  const lokalnaSirina = celija
    ? celija.clientWidth -
      (parseFloat(stilCelije.paddingLeft) || 0) -
      (parseFloat(stilCelije.paddingRight) || 0)
    : width;
  const sirinaGrafa = Math.max(
    1,
    Math.floor(Math.min(width, lokalnaSirina))
  );
  const mobilno = sirinaGrafa &lt; 480;
  const vrloUsko = sirinaGrafa &lt; 330;
  const skupine = mobilno
    ? ["A", "B"]
    : ["Skupina A", "Skupina B"];
  const redoslijedMetrika = [
    mobilno ? "Lažno +" : "Lažno pozitivni",
    mobilno ? "Lažno −" : "Lažno negativni",
    vrloUsko
      ? "Pred. vr."
      : "Pred. vrijednost",
    "Točnost"
  ];

  const mjerila = (skupina, temeljna) =&gt; {
    const pozitivnaPrediktivna =
      temeljna * tpr /
      (temeljna * tpr + (1 - temeljna) * fpr);
    const tocnost = temeljna * tpr + (1 - temeljna) * tnr;
    return [
      {skupina, metrika: redoslijedMetrika[0], stopa: fpr},
      {skupina, metrika: redoslijedMetrika[1], stopa: fnr},
      {
        skupina,
        metrika: redoslijedMetrika[2],
        stopa: pozitivnaPrediktivna
      },
      {skupina, metrika: redoslijedMetrika[3], stopa: tocnost}
    ];
  };
  const redoviA = mjerila(skupine[0], w17_par.temeljna_a);
  const redoviB = mjerila(skupine[1], w17_par.temeljna_b);
  const redovi = [...redoviA, ...redoviB];
  const vanjskeOznake = redovi;
  const sazetakTekst =
    `Prag ${formatPostotak.format(w17_par.prag)}. ` +
    `Skupina A: prediktivna vrijednost ${formatPostotak.format(redoviA[2].stopa)}, ` +
    `točnost ${formatPostotak.format(redoviA[3].stopa)}; ` +
    `skupina B: prediktivna vrijednost ${formatPostotak.format(redoviB[2].stopa)}, ` +
    `točnost ${formatPostotak.format(redoviB[3].stopa)}.`;

  const graf = Plot.plot({
    width: sirinaGrafa,
    height: mobilno ? 500 : 480,
    marginTop: mobilno ? 34 : 40,
    marginRight: mobilno ? 44 : 80,
    marginBottom: mobilno ? 52 : 46,
    marginLeft: vrloUsko ? 86 : 140,
    style: {
      background: "transparent",
      color: tinta,
      fontFamily: "var(--tok-font-mono)",
      fontSize: mobilno ? "14px" : "13px"
    },
    x: {
      label: "Stopa",
      domain: [0, 1],
      grid: true,
      tickFormat: d =&gt; `${Math.round(d * 100)} %`
    },
    y: {
      label: null,
      domain: redoslijedMetrika
    },
    fy: {
      label: null,
      domain: skupine
    },
    color: {
      domain: skupine,
      range: [bojaA, bojaB],
      legend: false
    },
    marks: [
      Plot.barX(redovi, {
        x: "stopa",
        y: "metrika",
        fy: "skupina",
        fill: "skupina",
        insetTop: 3,
        insetBottom: 3
      }),
      Plot.text(vanjskeOznake, {
        x: "stopa",
        y: "metrika",
        fy: "skupina",
        text: d =&gt; formatPostotak.format(d.stopa),
        dx: 5,
        textAnchor: "start",
        fill: tinta
      }),
      Plot.ruleX([0], {stroke: pravilo})
    ]
  });
  const ziviSazetak = document.getElementById("w17-status");
  if (ziviSazetak) ziviSazetak.textContent = sazetakTekst;
  return graf;
}









Slika 1: Istraživač pravednosti — četiri mjerila po skupini pri zajedničkom klasifikacijskom pragu.





Što isprobati.

Postavite obje temeljne stope na 20 % i usporedite sva četiri mjerila.
Vratite skupinu B na 45 % te pronađite mjerila koja se razilaze iako je prag zajednički.
Pomaknite prag prema 0,30 pa prema 0,70 i provjerite može li jedno podešenje istodobno smanjiti obje vrste pogreške.


Jednaka ocjena, različite pogreške. Analiza instrumenata za procjenu rizika pokazala je sukob između kalibracije i jednakosti određenih stopa pogreške kada se temeljne stope razlikuju (Chouldechova 2017.).
Tvrdnja da je model „pravedan” zato nije potpuna bez imenovanja mjerila, skupina, praga i posljedica. Agregatna točnost može ostati jednaka dok se vrste pogrešaka vrlo nejednako raspoređuju.


Asistent može izračunati tablice zabune i mjerila po skupinama. Treba mu dati stvarne ishode, predviđene rezultate i prag, bez osobnih identifikatora. Provjeravamo nazivnike svake stope i tražimo da sukob mjerila ne riješi neobrazloženom tvrdnjom da je jedno „najpoštenije”.

Izračunaj tablicu zabune i stope pogrešaka zasebno po skupinama. Objasni kako prag i temeljne stope mijenjaju mjerila, a vrijednosni izbor ostavi jasno označenim.



Model ima jednaku ukupnu točnost u dvjema skupinama, a prag je za obje jednak. Zato je algoritam pravedan i nije potrebno pregledavati zasebne stope pogreške.

Glagoli obrade podataka
Obrada podataka u dpljru svodi se na nekoliko glagola koji se slažu cjevovodom. Svaki uzima tablicu i vraća tablicu, zbog čega se mogu nizati bez ograničenja.
Glagol filter() bira retke koji zadovoljavaju uvjet.

anketa_mreze |&gt;
  filter(dob &lt; 25) |&gt;
  head(3)

# A tibble: 3 × 5
  ispitanik   dob dobna_skupina minute_dnevno povjerenje
  &lt;chr&gt;     &lt;dbl&gt; &lt;fct&gt;                 &lt;dbl&gt;      &lt;dbl&gt;
1 I001         22 18 do 24                 69          6
2 I002         22 18 do 24                 53          8
3 I003         24 18 do 24                 83         10


Uvjeti se kombiniraju logičkim operatorima. Znak & znači „i”, znak | znači „ili”, a znak ! preokreće uvjet. Zarez među uvjetima unutar filter() radi isto što i &.

anketa_mreze |&gt;
  filter(dob &lt; 25, minute_dnevno &gt; 100) |&gt;
  nrow()

[1] 22

anketa_mreze |&gt;
  filter(povjerenje &lt;= 3 | povjerenje &gt;= 9) |&gt;
  nrow()

[1] 53


Kada provjeravate pripada li vrijednost jednoj od više kategorija, umjesto niza uvjeta spojenih znakom | upotrijebite operator %in%.

anketa_mreze |&gt;
  filter(dobna_skupina %in% c("18 do 24", "25 do 34")) |&gt;
  nrow()

[1] 174


Čest početnički promašaj jest pisanje dobna_skupina == "18 do 24" | "25 do 34". Takav izraz ne javlja grešku, a ne radi ono što se očekuje, jer R drugi dio tumači kao samostalnu vrijednost koja je uvijek istinita. Operator %in% uklanja tu zamku i uz to je čitljiviji.
Za raspone postoji between().

anketa_mreze |&gt;
  filter(between(minute_dnevno, 60, 180)) |&gt;
  nrow()

[1] 90


Glagol select() bira stupce, a znak minus ih uklanja.

