Glagol mutate() stvara nove stupce ili mijenja postojeće.

anketa_mreze |&gt;
  mutate(sati_dnevno = minute_dnevno / 60) |&gt;
  select(ispitanik, minute_dnevno, sati_dnevno) |&gt;
