Argumenti mogu imati zadane vrijednosti, koje se koriste kada ih pozivatelj ne navede.

opis_zaokruzeno &lt;- function(x, decimala = 1) {
  opis(x) |&gt;
    mutate(across(c(sredina, medijan, sd), \(v) round(v, decimala)))
}

